/**
 * The on-screen message action taken when an alarm fires.
 * See krpc_SpaceCenter_Alarm_MessageAction().
 */
typedef enum {
  /**
   * Do not display a message when the alarm fires.
   */
  KRPC_SPACECENTER_ALARMMESSAGEACTION_NOMESSAGE = 0,
  /**
   * Display a message when the alarm fires.
   */
  KRPC_SPACECENTER_ALARMMESSAGEACTION_MESSAGE = 1,
  /**
   * Display a message only if the alarm's vessel is not the currently active vessel.
   */
  KRPC_SPACECENTER_ALARMMESSAGEACTION_MESSAGEIFNOTACTIVEVESSEL = 2
} krpc_SpaceCenter_AlarmMessageAction_t;

/**
 * The type of an alarm. See krpc_SpaceCenter_Alarm_Type().
 */
typedef enum {
  /**
   * An alarm for a specific date/time or a specific period in the future.
   */
  KRPC_SPACECENTER_ALARMTYPE_RAW = 0,
  /**
   * An alarm for the next apoapsis of a vessel.
   */
  KRPC_SPACECENTER_ALARMTYPE_APOAPSIS = 1,
  /**
   * An alarm for the next periapsis of a vessel.
   */
  KRPC_SPACECENTER_ALARMTYPE_PERIAPSIS = 2,
  /**
   * An alarm based on a maneuver node on the vessel's flight path.
   */
  KRPC_SPACECENTER_ALARMTYPE_MANEUVER = 3,
  /**
   * An alarm for the next sphere of influence change on the vessel's flight path.
   */
  KRPC_SPACECENTER_ALARMTYPE_SOICHANGE = 4,
  /**
   * An alarm for the next planetary transfer window from the vessel's current
   * orbit to a target body.
   */
  KRPC_SPACECENTER_ALARMTYPE_TRANSFERWINDOW = 5,
  /**
   * The alarm is of a type not recognized by kRPC. Typically this is a type
   * introduced by a mod.
   */
  KRPC_SPACECENTER_ALARMTYPE_UNKNOWN = 6
} krpc_SpaceCenter_AlarmType_t;

/**
 * The warp action taken when an alarm fires.
 * See krpc_SpaceCenter_Alarm_WarpAction().
 */
typedef enum {
  /**
   * Do not change time warp when the alarm fires.
   */
  KRPC_SPACECENTER_ALARMWARPACTION_NOCHANGE = 0,
  /**
   * Drop out of time warp when the alarm fires.
   */
  KRPC_SPACECENTER_ALARMWARPACTION_STOPWARP = 1,
  /**
   * Pause the game when the alarm fires.
   */
  KRPC_SPACECENTER_ALARMWARPACTION_PAUSEGAME = 2
} krpc_SpaceCenter_AlarmWarpAction_t;

/**
 * The mode of the altitude reported on the altimeter.
 * See krpc_SpaceCenter_AltimeterMode().
 */
typedef enum {
  /**
   * The altimeter is in the default mode.
   */
  KRPC_SPACECENTER_ALTIMETERMODE_DEFAULT = 0,
  /**
   * The altimeter is in the "Above Sea Level" mode.
   */
  KRPC_SPACECENTER_ALTIMETERMODE_ASL = 1,
  /**
   * The altimeter is in the "Above Ground Level" mode.
   */
  KRPC_SPACECENTER_ALTIMETERMODE_AGL = 2
} krpc_SpaceCenter_AltimeterMode_t;

/**
 * The kind of target a RealAntennas antenna points at. See krpc_SpaceCenter_Antenna_TargetMode().
 */
typedef enum {
  /**
   * The antenna has no target. Omnidirectional antennas have none.
   */
  KRPC_SPACECENTER_ANTENNATARGETMODE_NONE = 0,
  /**
   * A vessel. See krpc_SpaceCenter_Antenna_TargetVessel().
   */
  KRPC_SPACECENTER_ANTENNATARGETMODE_VESSEL = 1,
  /**
   * The center of a body. See krpc_SpaceCenter_Antenna_TargetBody().
   */
  KRPC_SPACECENTER_ANTENNATARGETMODE_BODY = 2,
  /**
   * A position on or above a body. See krpc_SpaceCenter_Antenna_SetTargetPosition().
   */
  KRPC_SPACECENTER_ANTENNATARGETMODE_POSITION = 3,
  /**
   * An azimuth and elevation from the vessel's position. See
   * krpc_SpaceCenter_Antenna_SetTargetAzimuthElevation().
   */
  KRPC_SPACECENTER_ANTENNATARGETMODE_AZIMUTHELEVATION = 4,
  /**
   * A direction relative to the vessel's orbital velocity. See
   * krpc_SpaceCenter_Antenna_SetTargetOrbitRelative().
   */
  KRPC_SPACECENTER_ANTENNATARGETMODE_ORBITRELATIVE = 5
} krpc_SpaceCenter_AntennaTargetMode_t;

/**
 * When the auto-pilot's control loop runs within a server update, relative to the calls
 * the update executes. See krpc_SpaceCenter_AutoPilot_UpdateMode().
 */
typedef enum {
  /**
   * The default. The control loop runs once the update has executed the calls it
   * received, so a target set during a tick is flown on that tick.
   */
  KRPC_SPACECENTER_AUTOPILOTUPDATEMODE_AFTERCALLS = 0,
  /**
   * The control loop runs before the update executes any calls, so calls made during a
   * tick see the attitude error and control output it computed for that tick.
   */
  KRPC_SPACECENTER_AUTOPILOTUPDATEMODE_BEFORECALLS = 1,
  /**
   * The control loop runs only when krpc_SpaceCenter_AutoPilot_Update() is called, so a
   * program chooses where among its own calls it runs.
   */
  KRPC_SPACECENTER_AUTOPILOTUPDATEMODE_MANUAL = 2
} krpc_SpaceCenter_AutoPilotUpdateMode_t;

